import {characterHeightScale} from './character-heights.js';
const fullBodyMain=['taei','seoyeon','yeogyeong','soyul','iseo','dogyeom'];
const fullBodyFair=['jihoo','naeun','dohyun','dayeon','chaerin','junseo'];
export function characterVisual(id,acting={}){const main=fullBodyMain.indexOf(id),fair=fullBodyFair.indexOf(id),index=main>=0?main:fair;if(index<0)return null;return {heightScale:characterHeightScale(id),mode:['neutral','warm','serious',undefined].includes(acting.emotion)?'fullbody':'expression',sheet:main>=0?'main':'fair',x:(index%3)*50,y:Math.floor(index/3)*100};}
let characterLayoutObserver=null,characterObservedPanel=null;
export function fitCharacterStage(){const stage=document.querySelector('.vn-stage'),panel=stage?.querySelector('.vn-panel');if(!stage||!panel)return;const box=stage.getBoundingClientRect(),p=panel.getBoundingClientRect(),top=Math.max(90,Math.min(160,box.height*.16)),height=Math.max(70,Math.min(650,p.top-box.top-top-28,box.width*(stage.querySelectorAll('.cast-member').length===3?.28:.42)*9/4));stage.style.setProperty('--fullbody-top',top+'px');stage.style.setProperty('--fullbody-height',height+'px');if(characterObservedPanel!==panel){characterLayoutObserver?.disconnect();characterObservedPanel=panel;characterLayoutObserver??=new ResizeObserver(()=>requestAnimationFrame(fitCharacterStage));characterLayoutObserver.observe(panel);}}
